import org.openqa.selenium.*;
import org.openqa.selenium.interactions.Actions;

public class ActionsLab {
    public boolean dragAndDropToTarget(WebDriver driver) {
        WebElement source = driver.findElement(By.id("draggable"));
        WebElement target = driver.findElement(By.id("dropzone"));
        new Actions(driver)
            .dragAndDrop(source, target)
            .perform();
        return true;
    }

    public void fillAndSubmit(WebDriver driver) {
        WebElement input = driver.findElement(By.id("search"));
        input.sendKeys("test query");
        new Actions(driver)
            .sendKeys(Keys.ENTER)
            .perform();
    }
}

